labels = [24, 27, 6, 2, 4, 18, 35, 28, 36, 23, 0, 34, 3, 31, 30, 15]
edges = []
for g in range(4):
    for i in range(4):
        for j in range(i+1,4):
            edges.append((g*4+i, g*4+j))
for g in range(3):
    for i in range(4):
        edges.append((g*4+i, (g+1)*4+i))

assert len(set(labels))==16
assert all(0<=x<=36 for x in labels)
diffs=[abs(labels[a]-labels[b]) for a,b in edges]
print(sorted(diffs))
assert len(set(diffs))==36
assert 0 not in diffs
print("OK")
